import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Phone } from 'lucide-react';
import { Button } from '@/components/ui/button';

const navLinks = [
  { label: 'Home', href: '/' },
  { label: 'Services', href: '/services' },
  { label: 'About', href: '/about' },
  { label: 'Contact', href: '/contact' },
];

export default function Header() {
  const [mobileOpen, setMobileOpen] = useState(false);
  const location = useLocation();

  return (
    <header className="sticky top-0 z-50 bg-background/95 backdrop-blur-sm border-b border-border shadow-sm">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-20 md:h-24">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Spotless logo"
              className="h-10 md:h-12 w-auto object-contain shrink-0 self-center"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            {navLinks.map((link) => (
              <Link
                key={link.href}
                to={link.href}
                className={`text-sm font-medium transition-colors duration-200 hover:text-primary ${
                  location.pathname === link.href
                    ? 'text-primary'
                    : 'text-foreground/70'
                }`}
              >
                {link.label}
              </Link>
            ))}
          </nav>

          {/* CTA */}
          <div className="hidden md:flex items-center gap-3">
            <a
              href="tel:+15555550100"
              className="flex items-center gap-2 text-sm font-semibold text-foreground/80 hover:text-primary transition-colors duration-200"
            >
              <Phone className="w-4 h-4 text-primary" />
              (555) 555-0100
            </a>
            <Button asChild size="sm" className="rounded-full px-5">
              <Link to="/contact">Get a Free Quote</Link>
            </Button>
          </div>

          {/* Mobile toggle */}
          <button
            className="md:hidden p-2 rounded-md text-foreground/70 hover:text-primary transition-colors"
            onClick={() => setMobileOpen(!mobileOpen)}
            aria-label="Toggle menu"
          >
            {mobileOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {mobileOpen && (
        <div className="md:hidden bg-background border-t border-border px-4 pb-6 pt-4">
          <nav className="flex flex-col gap-4 mb-5">
            {navLinks.map((link) => (
              <Link
                key={link.href}
                to={link.href}
                onClick={() => setMobileOpen(false)}
                className={`text-base font-medium transition-colors hover:text-primary ${
                  location.pathname === link.href ? 'text-primary' : 'text-foreground/70'
                }`}
              >
                {link.label}
              </Link>
            ))}
          </nav>
          <a
            href="tel:+15555550100"
            className="flex items-center gap-2 text-sm font-semibold text-foreground/80 mb-3"
          >
            <Phone className="w-4 h-4 text-primary" />
            (555) 555-0100
          </a>
          <Button asChild className="w-full rounded-full">
            <Link to="/contact" onClick={() => setMobileOpen(false)}>
              Get a Free Quote
            </Link>
          </Button>
        </div>
      )}
    </header>
  );
}

import { Link } from 'react-router-dom';
import { motion } from 'motion/react';
import { Helmet } from '@dr.pogodin/react-helmet';
import { Star, Phone, ShieldCheck, Leaf, BadgeCheck, ArrowRight, Sparkles } from 'lucide-react';
import { Button } from '@/components/ui/button';

// ─── Animation helpers ────────────────────────────────────────────────────────
const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.35, ease: 'easeOut' as const } },
};

const stagger = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.12 } },
};

// ─── Data ─────────────────────────────────────────────────────────────────────
const services = [
  {
    title: 'Regular Cleaning',
    description:
      'Weekly or bi-weekly visits that keep your home consistently fresh — dusting, vacuuming, mopping, and sanitizing all the essentials.',
    slot: '/airo-assets/images/pages/home/service-regular',
    alt: 'Clean bright living room',
  },
  {
    title: 'Deep Cleaning',
    description:
      'A thorough top-to-bottom clean for when your home needs extra attention — inside appliances, baseboards, grout, and every corner.',
    slot: '/airo-assets/images/pages/home/service-deep-clean',
    alt: 'Sparkling clean bathroom',
  },
  {
    title: 'Move-In / Move-Out',
    description:
      'Start fresh or leave on a high note. We make sure every surface is spotless so you can focus on the move itself.',
    slot: '/airo-assets/images/pages/home/service-moveinout',
    alt: 'Clean empty bedroom ready to move in',
  },
  {
    title: 'Home Office Cleaning',
    description:
      'A clean workspace means a clear mind. We keep your home office dust-free, organized, and ready for your best work.',
    slot: '/airo-assets/images/pages/home/service-windows',
    alt: 'Bright organized home office',
  },
];

const trustSignals = [
  {
    icon: ShieldCheck,
    title: 'Insured & Bonded',
    description: 'Fully insured for your peace of mind. Your home and belongings are always protected.',
  },
  {
    icon: BadgeCheck,
    title: 'Satisfaction Guaranteed',
    description: "Not happy? We'll come back and make it right — no questions asked.",
  },
  {
    icon: Leaf,
    title: 'Eco-Friendly Products',
    description: 'We use non-toxic, environmentally safe cleaning products that are safe for kids and pets.',
  },
];

const testimonials = [
  {
    name: 'Sarah M.',
    location: 'Riverside Heights',
    quote:
      "I've tried three other cleaning services and none of them come close. My house has never looked this good. They even cleaned behind the fridge!",
    rating: 5,
  },
  {
    name: 'James & Priya K.',
    location: 'Oakwood District',
    quote:
      'We hired Spotless for a move-out clean and our landlord was genuinely impressed. Got our full deposit back. Worth every penny.',
    rating: 5,
  },
  {
    name: 'Linda T.',
    location: 'Maplewood',
    quote:
      'Reliable, thorough, and always on time. I love coming home on cleaning day — it feels like a hotel every single time.',
    rating: 5,
  },
];

// ─── Sub-components ───────────────────────────────────────────────────────────
function StarRating({ count }: { count: number }) {
  return (
    <div className="flex items-center gap-0.5">
      {Array.from({ length: count }).map((_, i) => (
        <Star key={i} className="w-4 h-4 fill-yellow-400 text-yellow-400" />
      ))}
    </div>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────
export default function HomePage() {
  return (
    <>
      <Helmet>
        <title>Spotless — Professional House Cleaning Services</title>
        <meta
          name="description"
          content="Reliable, eco-friendly residential cleaning services. Regular, deep, and move-in/out cleaning. Get a free quote today."
        />
      </Helmet>

      {/* ── HERO ─────────────────────────────────────────────────────────── */}
      <section className="relative min-h-[88vh] flex items-center overflow-hidden">
        {/* Background image */}
        <div className="absolute inset-0">
          <img
            src="/airo-assets/images/pages/home/hero"
            alt="Beautifully clean modern kitchen"
            className="w-full h-full object-cover"
            fetchPriority="high"
          />
          <div className="absolute inset-0 bg-gradient-to-r from-foreground/75 via-foreground/50 to-foreground/10" />
        </div>

        {/* Sparkle decoration */}
        <motion.div
          className="absolute top-16 right-16 hidden lg:block"
          animate={{ rotate: [0, 15, -10, 0], scale: [1, 1.15, 0.95, 1] }}
          transition={{ duration: 6, repeat: Infinity, ease: 'easeInOut' }}
        >
          <Sparkles className="w-10 h-10 text-primary/60" />
        </motion.div>

        {/* Content */}
        <div className="relative z-10 max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-24">
          <motion.div
            variants={stagger}
            initial="hidden"
            animate="visible"
            className="max-w-2xl"
          >
            <motion.p variants={fadeUp} className="text-primary font-semibold text-sm uppercase tracking-widest mb-4">
              Professional House Cleaning
            </motion.p>

            <motion.h1
              variants={fadeUp}
              className="text-5xl sm:text-6xl lg:text-7xl font-bold text-white leading-[1.05] mb-6"
            >
              A Spotless Home,{' '}
              <span className="text-primary">Every Time.</span>
            </motion.h1>

            <motion.p variants={fadeUp} className="text-white/80 text-lg sm:text-xl leading-relaxed mb-8 max-w-xl">
              Trusted residential cleaning that fits your schedule. Eco-friendly products, insured professionals, and a satisfaction guarantee.
            </motion.p>

            {/* Star rating */}
            <motion.div variants={fadeUp} className="flex items-center gap-3 mb-8">
              <StarRating count={5} />
              <span className="text-white/80 text-sm font-medium">4.9 · 200+ happy customers</span>
            </motion.div>

            {/* CTAs */}
            <motion.div variants={fadeUp} className="flex flex-col sm:flex-row items-start gap-4">
              <Button asChild size="lg" className="rounded-full px-8 text-base font-semibold shadow-lg">
                <Link to="/contact">Get a Free Quote</Link>
              </Button>
              <a
                href="tel:+15555550100"
                className="flex items-center gap-2 text-white font-semibold text-base hover:text-primary transition-colors duration-200 mt-1"
              >
                <Phone className="w-5 h-5" />
                (555) 555-0100
              </a>
            </motion.div>
          </motion.div>
        </div>
      </section>

      {/* ── SERVICES ─────────────────────────────────────────────────────── */}
      <section className="py-24 bg-background">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <motion.div
            variants={stagger}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="mb-16"
          >
            <motion.p variants={fadeUp} className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">
              What We Offer
            </motion.p>
            <motion.h2 variants={fadeUp} className="text-4xl sm:text-5xl font-bold text-foreground">
              Services Built Around Your Home
            </motion.h2>
          </motion.div>

          <div className="flex flex-col gap-16">
            {services.map((service, i) => (
              <motion.div
                key={service.title}
                variants={stagger}
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                className={`grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-14 items-center ${
                  i % 2 === 1 ? 'md:[direction:rtl]' : ''
                }`}
              >
                {/* Image */}
                <motion.div
                  variants={fadeUp}
                  className="relative overflow-hidden rounded-2xl shadow-lg group"
                  style={{ direction: 'ltr' }}
                  whileHover={{ y: -4, boxShadow: '0 20px 40px rgba(0,0,0,0.12)' }}
                  transition={{ duration: 0.2 }}
                >
                  <img
                    src={service.slot}
                    alt={service.alt}
                    className="w-full h-72 md:h-80 object-cover transition-transform duration-500 group-hover:scale-105"
                  />
                </motion.div>

                {/* Text */}
                <motion.div variants={fadeUp} style={{ direction: 'ltr' }} className="flex flex-col justify-center">
                  <span className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">
                    0{i + 1}
                  </span>
                  <h3 className="text-3xl font-bold text-foreground mb-4">{service.title}</h3>
                  <p className="text-muted-foreground text-base leading-relaxed mb-6">{service.description}</p>
                  <Link
                    to="/services"
                    className="inline-flex items-center gap-2 text-primary font-semibold text-sm hover:gap-3 transition-all duration-200"
                  >
                    Learn more <ArrowRight className="w-4 h-4" />
                  </Link>
                </motion.div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* ── WHY CHOOSE US ─────────────────────────────────────────────────── */}
      <section className="py-24 bg-muted">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <motion.div
            variants={stagger}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center"
          >
            {/* Left: headline */}
            <motion.div variants={fadeUp}>
              <p className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">Why Spotless</p>
              <h2 className="text-4xl sm:text-5xl font-bold text-foreground leading-tight mb-6">
                We Take the Worry Out of Clean
              </h2>
              <p className="text-muted-foreground text-lg leading-relaxed">
                Every cleaner on our team is background-checked, trained, and genuinely cares about the quality of their work. We're not just cleaning your home — we're earning your trust.
              </p>
            </motion.div>

            {/* Right: trust signals */}
            <motion.div variants={stagger} className="flex flex-col gap-6">
              {trustSignals.map((signal) => (
                <motion.div
                  key={signal.title}
                  variants={fadeUp}
                  className="flex items-start gap-5 bg-background rounded-2xl p-6 shadow-sm"
                >
                  <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center shrink-0">
                    <signal.icon className="w-6 h-6 text-primary" />
                  </div>
                  <div>
                    <h3 className="font-bold text-foreground text-lg mb-1">{signal.title}</h3>
                    <p className="text-muted-foreground text-sm leading-relaxed">{signal.description}</p>
                  </div>
                </motion.div>
              ))}
            </motion.div>
          </motion.div>
        </div>
      </section>

      {/* ── TESTIMONIALS ─────────────────────────────────────────────────── */}
      <section className="py-24 bg-background">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <motion.div
            variants={stagger}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="mb-14 text-center"
          >
            <motion.p variants={fadeUp} className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">
              Customer Stories
            </motion.p>
            <motion.h2 variants={fadeUp} className="text-4xl sm:text-5xl font-bold text-foreground">
              Homeowners Love Spotless
            </motion.h2>
          </motion.div>

          <motion.div
            variants={stagger}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="grid grid-cols-1 md:grid-cols-3 gap-6"
          >
            {testimonials.map((t) => (
              <motion.div
                key={t.name}
                variants={fadeUp}
                whileHover={{ y: -4, boxShadow: '0 16px 32px rgba(0,0,0,0.08)' }}
                transition={{ duration: 0.2 }}
                className="bg-card border border-border rounded-2xl p-7 flex flex-col gap-4"
              >
                <StarRating count={t.rating} />
                <p className="text-foreground/80 text-base leading-relaxed flex-1">"{t.quote}"</p>
                <div>
                  <p className="font-semibold text-foreground text-sm">{t.name}</p>
                  <p className="text-muted-foreground text-xs">{t.location}</p>
                </div>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </section>

      {/* ── CTA BAND ─────────────────────────────────────────────────────── */}
      <section className="py-20 bg-primary">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <motion.div
            variants={stagger}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="flex flex-col lg:flex-row items-center justify-between gap-10"
          >
            <motion.div variants={fadeUp} className="text-center lg:text-left">
              <h2 className="text-3xl sm:text-4xl font-bold text-primary-foreground mb-3">
                Ready for a Cleaner Home?
              </h2>
              <p className="text-primary-foreground/80 text-lg">
                Get your free, no-obligation quote today. We'll be in touch within 24 hours.
              </p>
            </motion.div>

            <motion.div variants={fadeUp} className="flex flex-col sm:flex-row items-center gap-4 shrink-0">
              <a
                href="tel:+15555550100"
                className="flex items-center gap-2 text-primary-foreground font-bold text-lg hover:text-primary-foreground/80 transition-colors duration-200"
              >
                <Phone className="w-5 h-5" />
                (555) 555-0100
              </a>
              <Button
                asChild
                size="lg"
                variant="secondary"
                className="rounded-full px-8 font-semibold text-base"
              >
                <Link to="/contact">Request a Quote</Link>
              </Button>
            </motion.div>
          </motion.div>
        </div>
      </section>
    </>
  );
}

